wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
